-- Questões originais de estudo: Deitel e Deitel, Java: como programar, 10ª edição.
-- Tradução brasileira do PDF fornecido: Pearson Education do Brasil, 2017.
-- Contexto dos recursos: Java SE 8. Não são questões oficiais nem exercícios transcritos.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens entram como rascunhos. Revise antes de publicar.
-- Páginas são do arquivo PDF, não da numeração impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve registros existentes.
-- Capítulo 6: Métodos: um exame mais profundo — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('4fec9225-8adb-583f-91c5-f92282bb92f6', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Linguagem de Programação', 'Fácil', 'Dividir um programa em métodos favorece:', '["Eliminação de testes.","Modularização e reutilização.","Variáveis globais obrigatórias.","Ausência de parâmetros.","Duplicação obrigatória."]'::jsonb, 1, 'Métodos separam responsabilidades e podem ser reutilizados.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.2, páginas 193–194 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('31646d37-1334-5c0f-8d06-773876feba7d', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Linguagem de Programação', 'Fácil', 'Um método static pode ser chamado normalmente por:', '["Qualquer variável não inicializada.","Nome da classe e nome do método.","Somente super.","Somente this.","Um construtor privado de outra classe."]'::jsonb, 1, 'A chamada não exige uma instância específica.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.3, páginas 195 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0d91f6b3-48a9-5931-8db1-8d281bbae4f1', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Linguagem de Programação', 'Fácil', 'Um método static possui referência this?', '["Sim, sempre.","Sim, quando public.","Somente em main.","Somente se retornar int.","Não."]'::jsonb, 4, 'This representa a instância atual, inexistente no contexto estático.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.3, páginas 195 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c81ed016-f33d-5393-8b78-bbdf32e2b1c4', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Linguagem de Programação', 'Médio', 'Qual valor de `Math.max(8,3)`?', '["8.","24.","11.","5.","3."]'::jsonb, 0, 'Max retorna o maior argumento.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.3, páginas 195 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c8f8f629-9641-59a4-8901-6ff99650d522', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Linguagem de Programação', 'Médio', 'Qual valor de `Math.sqrt(81.0)`?', '["81.0.","8.0.","Erro.","9.0.","40.5."]'::jsonb, 3, 'A operação calcula a raiz quadrada.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.3, páginas 195 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e42df00e-eee6-529c-8a3a-5588f143f1cd', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Linguagem de Programação', 'Médio', 'Ao chamar um método, argumentos correspondem aos parâmetros por:', '["Posição e compatibilidade de tipos.","Nome do usuário.","Somente ordem alfabética.","Nome do arquivo.","Tamanho do comentário."]'::jsonb, 0, 'Os nomes locais dos argumentos não determinam essa associação.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.4, páginas 196–198 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f2e441bc-4149-52e3-a9c4-69f1b6ba3d12', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Linguagem de Programação', 'Médio', 'Um método declarado int pode retornar `return 3;`?', '["Sim, mas vira void.","Não, somente double.","Somente se construtor.","Sim.","Não, exige String."]'::jsonb, 3, 'O valor retornado precisa ser compatível com o retorno declarado.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.4, páginas 196–198 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f8e994b6-1021-5611-965e-b5dc6d79e6f8', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Linguagem de Programação', 'Médio', 'Um método não void deve retornar valor em todos os caminhos que podem terminar normalmente?', '["Não, null serve para qualquer primitivo.","Não, recebe sempre zero.","Sim.","Somente quando public.","Somente em main."]'::jsonb, 2, 'O compilador verifica os caminhos de retorno relevantes.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.5, páginas 199 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1eaea4b2-a518-576d-a76e-55fd20414dfa', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Linguagem de Programação', 'Médio', 'Cada chamada de método pode acrescentar à pilha:', '["Um quadro de ativação.","Uma nova classe-fonte.","Um pacote.","Uma janela obrigatória.","Uma licença."]'::jsonb, 0, 'O quadro mantém o contexto necessário à execução e ao retorno.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.6, páginas 200 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('07ffc4e0-55c3-5311-b436-64dd7f7bc8c9', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Linguagem de Programação', 'Médio', 'Ao terminar um método, o controle retorna normalmente:', '["Ao início da JVM.","Ao primeiro import.","Sempre ao início de main.","Ao construtor de Object.","Ao ponto apropriado de seu chamador."]'::jsonb, 4, 'A pilha de chamadas registra a continuação da execução.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.6, páginas 200 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('92b3f9eb-dfec-5f8e-8116-aeb438361754', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Linguagem de Programação', 'Médio', 'Passar int para parâmetro double normalmente admite:', '["Erro obrigatório.","Conversão para String.","Promoção numérica implícita.","Unboxing obrigatório.","Conversão para boolean."]'::jsonb, 2, 'O alargamento é uma conversão permitida nesse contexto.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.7, páginas 200 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c124a433-eb2d-5ebf-b2fd-893f80f8eae4', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Linguagem de Programação', 'Médio', 'Passar double para parâmetro int exige normalmente:', '["Conversão para boolean.","Apenas import.","Nenhum cuidado de tipo.","Promoção automática sem perdas.","Conversão explícita adequada."]'::jsonb, 4, 'Estreitamento pode descartar informação.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.7, páginas 200 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c02d8bcc-fb64-560d-9daa-feae476ef894', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Linguagem de Programação', 'Médio', 'Qual resultado de `(int) 7.9`?', '["8.","7.9.","Erro.","7.","0."]'::jsonb, 3, 'A conversão descarta a fração em direção a zero.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.7, páginas 200 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e1859099-64ba-5f35-b96e-419a0d32504e', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Linguagem de Programação', 'Médio', '`nextInt(6)` de um gerador compatível retorna valores em:', '["1 a 5.","-6 a 6.","0 a 5.","0 a 6.","1 a 6."]'::jsonb, 2, 'O limite superior inteiro é exclusivo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.9, páginas 202–205 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d5a438e5-5b0c-551c-b9c9-84b97b76b14a', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Linguagem de Programação', 'Médio', 'Qual expressão transforma `nextInt(6)` em valores de 1 a 6?', '["`nextInt(7)`.","`1 + nextInt(6)`.","`6 + nextInt(1)`.","`nextInt(6) - 1`.","`nextInt(5)`."]'::jsonb, 1, 'Adicionar um desloca o intervalo 0–5 para 1–6.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.9, páginas 202–205 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c54ee0b1-8af5-5dd2-960f-9351db9a7d6e', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Linguagem de Programação', 'Médio', 'Um enum permite definir:', '["Variáveis sem tipo.","Um conjunto de constantes nomeadas de um tipo.","Apenas palavras reservadas.","Somente números de ponto flutuante.","Uma única constante global sem classe."]'::jsonb, 1, 'Enums modelam alternativas fixas com identidade de tipo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.10, páginas 206–209 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('23b28d5e-4571-5fbc-9bcb-cd8bab25bf5f', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Linguagem de Programação', 'Médio', 'Uma variável local de mesmo nome de um campo pode:', '["Alterar o pacote.","Apagar o campo.","Sombrear esse campo em seu escopo.","Impedir usar this.campo em método de instância.","Transformar o campo em static."]'::jsonb, 2, 'Qualificar o campo com this pode desfazer a ambiguidade.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.11, páginas 210 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ef436b8a-c175-5334-b538-3c0db163fd7e', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Linguagem de Programação', 'Médio', 'Sobrecarga de métodos exige diferença em:', '["Apenas retorno.","Somente visibilidade.","Apenas nomes dos parâmetros.","Listas de parâmetros.","Somente comentários."]'::jsonb, 3, 'Quantidade, tipos ou ordem dos tipos podem distinguir assinaturas.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.12, páginas 211–212 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('02e54e32-fa73-54b4-b43f-da3b9f37f673', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Linguagem de Programação', 'Médio', 'Dois métodos diferem apenas no tipo de retorno. Isso basta para sobrecarga?', '["Somente se public.","Somente para int e double.","Sim, em qualquer classe abstrata.","Sim, sempre.","Não."]'::jsonb, 4, 'O retorno isoladamente não distingue assinaturas de métodos.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.12, páginas 211–212 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b9e4d9b3-643d-5394-846d-bc224d0566bd', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Linguagem de Programação', 'Médio', 'Um método recebe int x e altera seu parâmetro. O int original do chamador muda automaticamente?', '["Não, o argumento primitivo foi passado por valor.","Sim, sempre.","Somente se x for positivo.","Somente se public.","Sim, porque Java usa referência para primitivos."]'::jsonb, 0, 'A alteração afeta a cópia local do parâmetro.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 6, seção 6.4, páginas 196–198 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
